import { SummaryTileType } from "../summaryTile";
export const getTypeClassName = (tileType) => {
    switch (tileType) {
        case SummaryTileType.Error:
            return "zen-summary-tile--error";
        case SummaryTileType.Warning:
            return "zen-summary-tile--warning";
        case SummaryTileType.Success:
            return "zen-summary-tile--success";
        /**
         * TODO: should be removed after {@link SummaryTileType.Info} is removed
        */
        case SummaryTileType.Info:
        case SummaryTileType.Active:
            return "zen-summary-tile--active";
        case SummaryTileType.Default:
        default:
            return "zen-summary-tile--default";
    }
};
